def rawHomologyMap (f : C(X, Y)) (n : ℕ) : RawPositiveHomology X n →ₗ[ℚ] RawPositiveHomology Y n :=
  (rawBoundaries X n).mapQ (rawBoundaries Y n) (rawCyclesMap f n)
    (rawCyclesMap_preserves_boundaries f n)

